/**
 * Sound effects: biro scribbles, page rustles and the till.
 * Files are generated by scripts/generate-sounds.mjs.
 *
 * Sounds respect the phone's silent switch and mix with whatever else is
 * playing (we never pause someone's music to play a page rustle).
 */
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { useSyncExternalStore } from 'react';

const sources = {
  scribble: require('@/assets/sounds/scribble.wav'),
  tick: require('@/assets/sounds/tick.wav'),
  rub: require('@/assets/sounds/rub.wav'),
  rustle: require('@/assets/sounds/rustle.wav'),
  till: require('@/assets/sounds/till.wav'),
} as const;

export type Sfx = keyof typeof sources;

const players: Partial<Record<Sfx, AudioPlayer>> = {};
let enabled = true;
const listeners = new Set<() => void>();

function player(name: Sfx): AudioPlayer {
  const existing = players[name];
  if (existing) return existing;
  const created = createAudioPlayer(sources[name]);
  players[name] = created;
  return created;
}

/** Sets the audio mode and loads every sound, so the first tap isn't silent. */
export async function preloadSfx(): Promise<void> {
  try {
    await setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' });
    (Object.keys(sources) as Sfx[]).forEach(player);
  } catch (e) {
    // Sound is a nice-to-have: never let it break the app.
    console.warn('Sound effects unavailable', e);
  }
}

export function playSfx(name: Sfx): void {
  if (!enabled) return;
  try {
    const p = player(name);
    p.seekTo(0);
    p.play();
  } catch (e) {
    console.warn(`Could not play ${name}`, e);
  }
}

export function setSoundEnabled(on: boolean): void {
  enabled = on;
  if (!on) Object.values(players).forEach((p) => p?.pause());
  listeners.forEach((l) => l());
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** Current sound setting, for mute buttons. */
export function useSoundEnabled(): boolean {
  return useSyncExternalStore(subscribe, () => enabled, () => enabled);
}
